$string['settings:csp_course_pages_mode_desc'] = 'En-tête CSP facultatif sur les pages de cours où le widget de l\'assistant de cours IA est actif. <strong>Désactivé</strong> : aucun en-tête (par défaut). <strong>Signalement seul</strong> : envoie <code>Content-Security-Policy-Report-Only</code> — les navigateurs journalisent les violations mais ne bloquent rien. Utile pour une semaine d\'observation. <strong>Appliqué</strong> : envoie <code>Content-Security-Policy</code> — les navigateurs bloquent les sources d\'iframe, les requêtes et les autres chargements risqués hors liste d\'autorisation. Aide à limiter l\'impact de scripts arbitraires collés dans la configuration HTML supplémentaire du site (l\'incident IBL AI / Raison du 29/04/2026). N\'affecte pas les points de terminaison de [[tutorshort]], qui envoient toujours une CSP plus stricte.';
$string['settings:csp_mode_off'] = 'Désactivé (aucun en-tête sur les pages de cours)';
$string['settings:csp_mode_report_only'] = 'Signalement seul (journaliser les violations, sans bloquer)';
$string['settings:csp_mode_enforce'] = 'Appliquer (bloquer les chargements hors liste d\'autorisation)';
// v4.5.0: site-wide pedagogy defaults.
$string['settings:pedagogy_defaults_heading'] = 'Valeurs pédagogiques par défaut';
$string['settings:pedagogy_defaults_heading_desc'] = 'État par défaut, pour tout le site, de chaque fonctionnalité pédagogique. Activez une fonctionnalité ici et chaque cours en hérite, sauf si ce cours dispose d\'un remplacement explicite sur sa page de paramètres [[tutorshort]] (forcer l\'activation / forcer la désactivation). Lors de la mise à niveau vers la v4.5.0, tout remplacement par cours "forcer la désactivation" réglé sur l\'ancienne valeur par défaut <code>0</code> est effacé afin que les nouvelles valeurs par défaut globales s\'appliquent proprement. Désactivé par défaut — les mises à niveau depuis la v4.4.x n\'ont aucun effet tant qu\'un administrateur n\'active pas une fonctionnalité.';
$string['pedagogy:mastery'] = 'Suivi de la maîtrise activé par défaut';
$string['pedagogy:mastery_desc'] = 'Lorsque cette option est activée, tous les cours héritent du suivi de la maîtrise, sauf si le cours dispose de son propre remplacement. La maîtrise nécessite des objectifs d\'apprentissage sélectionnés — les cours sans objectifs reviennent à un comportement de repli sans incident, sans erreur.';
$string['pedagogy:socratic_mode'] = 'Mode socratique activé par défaut';
$string['pedagogy:socratic_mode_desc'] = 'Lorsque cette option est activée, [[tutorshort]] commence par des questions plutôt que par des réponses directes dans tous les cours, sauf si le cours dispose de son propre remplacement.';
$string['pedagogy:worked_examples'] = 'Amorce d\'exemples résolus activée par défaut';
$string['pedagogy:worked_examples_desc'] = 'Lorsque cette option est activée, l\'amorce de conversation « Montrez-moi un exemple résolu » apparaît dans tous les cours, sauf si le cours dispose de son propre remplacement.';
$string['pedagogy:flashcards'] = 'Cartes mémoire activées par défaut';
$string['pedagogy:flashcards_desc'] = 'Lorsque cette option est activée, les cartes mémoire à répétition espacée sont disponibles dans tous les cours, sauf si le cours dispose de son propre remplacement.';
$string['pedagogy:code_sandbox'] = 'Bac à sable Python activé par défaut';
$string['pedagogy:code_sandbox_desc'] = 'Lorsque cette option est activée, le bac à sable Python intégré au navigateur est disponible dans tous les cours, sauf si le cours dispose de son propre remplacement.';
$string['pedagogy:essay_feedback'] = 'Retour sur les dissertations activé par défaut';
$string['pedagogy:essay_feedback_desc'] = 'Lorsque cette option est activée, le retour d\'IA sur les dissertations est disponible dans tous les cours, sauf si le cours dispose de son propre remplacement.';
$string['pedagogy:per_course_inherit']     = 'Hériter de la valeur par défaut du site ({$a})';
$string['pedagogy:per_course_force_on']    = 'Forcer l\'activation pour ce cours';
$string['pedagogy:per_course_force_off']   = 'Forcer la désactivation pour ce cours';
$string['pedagogy:on']                     = 'activé';
$string['pedagogy:off']                    = 'désactivé';

// v4.6.0: vendor DPA gating + override editors.
$string['settings:vendor_data_heading'] = 'Données fournisseurs et coûts';
$string['settings:vendor_data_heading_desc'] = 'Contrôles de la page d\'administration facultative du statut DPA des fournisseurs et des éditeurs de remplacement qui permettent aux administrateurs de tenir à jour le tableau des fournisseurs et la grille tarifaire LLM livrés avec le plugin, sans modifier le code. Les deux éditeurs de remplacement sont en JSON ; une valeur vide revient aux valeurs par défaut codées en dur livrées avec le plugin.';
$string['settings:vendor_dpa_admin_page_enabled'] = 'Afficher la page d\'administration du statut DPA des fournisseurs';
$string['settings:vendor_dpa_admin_page_enabled_desc'] = 'Lorsque cette option est activée, "Statut DPA des fournisseurs" apparaît sous Administration du site → Plugins → Plugins locaux → Assistant de cours IA. La page affiche le tableau des fournisseurs fusionné avec le remplacement ci-dessous. Désactivé par défaut — la plupart des administrateurs n\'ont pas besoin de cette page.';
$string['settings:vendor_dpa_overrides'] = 'Remplacements du DPA des fournisseurs (JSON)';
$string['settings:vendor_dpa_overrides_desc'] = 'JSON object keyed by vendor id. Each value is an object whose fields override the hardcoded vendor row. Fields you do not specify fall through to the default. A new vendor key in the override is added to the table; edits apply per field. Malformed JSON is ignored at runtime — fix the parse error here when the saved value does not appear in the Vendor DPA page.';
$string['settings:rate_card_overrides'] = 'Remplacements de la grille tarifaire LLM (JSON)';
$string['settings:rate_card_overrides_desc'] = 'Objet JSON indexé par préfixe de nom de modèle. Chaque valeur est <code>{"input": float, "output": float}</code> en USD par 1 000 000 de jetons. Remplace l\'entrée de la grille tarifaire fournie pour ce préfixe. Exemple : <pre>{ "gpt-4o-mini": { "input": 0.15, "output": 0.60 }, "claude-sonnet-4.6": { "input": 3.00, "output": 15.00 } }</pre> En lecture seule depuis la v7.4.0 : ce champ est toujours fusionné (au-dessus de la grille de base fournie, en dessous du registre des modèles), si bien qu\'un remplacement existant continue de fonctionner, mais plus rien n\'y écrit et les nouveaux tarifs relèvent du registre des modèles, qui enregistre qui a défini chaque tarif et quand. L\'actualisation hebdomadaire écrasait auparavant l\'intégralité de ce champ, détruisant tout tarif saisi à la main lors de l\'exécution suivante.';

// v4.7.0: rate-card auto-refresh.
$string['settings:rate_card_auto_refresh'] = 'Actualisation automatique depuis la source en amont';
$string['settings:rate_card_auto_refresh_desc'] = 'Lorsque ce paramètre est activé, une tâche planifiée hebdomadaire (le lundi à 02h30, heure du serveur) récupère le JSON tarifaire en amont ci-dessous, le transforme au schéma de grille tarifaire de [[tutorshort]] et écrit chaque tarif dans le registre des modèles, ligne par ligne. Activé par défaut — désactivez-le pour figer la grille tarifaire sur ce qui a été récupéré ou saisi à la main en dernier. Un tarif saisi par un administrateur n\'est jamais écrasé par cette actualisation, et une exécution en échec n\'écrit rien du tout ; l\'état de la dernière actualisation apparaît sous le bouton Actualiser maintenant.';
$string['settings:rate_card_upstream_url'] = 'URL des tarifs en amont';
$string['settings:rate_card_upstream_url_desc'] = 'URL of a JSON manifest in LiteLLM\'s schema. Default points at the community-maintained file in the LiteLLM GitHub repo. URL is checked against the SSRF allowlist before fetch.';
$string['settings:rate_card_refresh_now'] = 'Actualiser maintenant';
$string['settings:rate_card_refresh_now_label'] = 'Actualiser la grille tarifaire depuis la source en amont';
$string['settings:rate_card_refresh_success'] = 'Grille tarifaire actualisée : {$a} entrées écrites.';
$string['settings:rate_card_refresh_error'] = 'Échec de l\'actualisation de la grille tarifaire : {$a}';
$string['settings:rate_card_last_refresh_at'] = 'Dernière actualisation : {$a}';
$string['settings:rate_card_last_refresh_success'] = 'La dernière récupération a réussi.';
$string['settings:rate_card_never_refreshed'] = 'Jamais actualisée.';
$string['task:refresh_rate_card'] = 'Actualiser la grille tarifaire LLM de [[tutorshort]] depuis la source amont';
