// v4.8.1: talking avatar (placeholder, default off, provider-neutral).
$string['pedagogy:talking_avatar'] = 'Avatar parlant activé par défaut';
$string['pedagogy:talking_avatar_desc'] = 'Lorsque cette option est activée, la surface d\'avatar parlant est activée dans tous les cours, sauf si le cours dispose de son propre remplacement. Nécessite un fournisseur configuré ci-dessous (D-ID, HeyGen, Tavus ou Synthesia Agents) ; sinon, le widget affiche un avis « configurez un fournisseur » et l\'avatar ne s\'anime pas.';
$string['settings:talking_avatar_heading'] = 'Avatar parlant';
$string['settings:talking_avatar_heading_desc'] = 'Choisissez le fournisseur d\'avatar parlant que [[tutorshort]] ouvre pour les étudiants lorsque la surface d\'avatar est activée. [[tutorshort]] fournit des pilotes pour D-ID (streaming WebRTC le moins cher), HeyGen (avatars interactifs basés sur LiveKit), Tavus (interface vidéo conversationnelle intégrable en iframe) et Synthesia Agents (produit d\'agent en temps réel, configuré dans le tableau de bord Synthesia). La clé et l\'identifiant de persona de chaque fournisseur apparaissent ci-dessous ; seul le fournisseur choisi doit être renseigné. Chaque appel sortant fait l\'objet d\'une vérification SSRF.';
$string['settings:talking_avatar_provider'] = 'Fournisseur d\'avatar parlant';
$string['settings:talking_avatar_provider_desc'] = 'Choisissez le fournisseur dont la clé et l\'identifiant de persona sont renseignés ci-dessous. Laissez sur <em>Aucun</em> tant que l\'établissement n\'a pas donné son accord ; la valeur pédagogique par défaut apparaît toujours dans <em>Valeurs pédagogiques par défaut</em>, mais le widget affiche un avis de configuration au lieu d\'un avatar.';
$string['settings:talking_avatar_provider_none'] = 'Aucun (avatar désactivé)';
$string['settings:talking_avatar_provider_did'] = 'D-ID Streaming Talks';
$string['settings:talking_avatar_provider_heygen'] = 'HeyGen Interactive Avatar';
$string['settings:talking_avatar_provider_tavus'] = 'Tavus Conversational Video';
$string['settings:talking_avatar_provider_synthesia'] = 'Synthesia Agents (temps réel)';
$string['settings:talking_avatar_did_api_key'] = 'Clé API D-ID';
$string['settings:talking_avatar_did_api_key_desc'] = 'Chaîne <code>email:api-key</code> encodée en Base64, issue de <a href="https://studio.d-id.com/account-settings" target="_blank" rel="noopener">D-ID Studio → Compte → Clés API</a>. Envoyée sous la forme <code>Authorization: Basic …</code>.';
$string['settings:talking_avatar_did_persona_id'] = 'URL de l\'image source D-ID';
$string['settings:talking_avatar_did_persona_id_desc'] = 'URL HTTPS publique de l\'image fixe que D-ID anime (ou une URL de présentateur Studio telle que <code>https://create-images-results.d-id.com/…</code>). Requise pour chaque flux.';
