$string['settings:talking_avatar_heygen_persona_id'] = 'Identifiant d\'avatar interactif HeyGen';
$string['settings:talking_avatar_heygen_persona_id_desc'] = 'Identifiant d\'avatar issu du tableau de bord HeyGen Streaming Avatar (ex. : <code>Tyler-incasualsuit-20220721</code>).';
$string['settings:talking_avatar_tavus_api_key'] = 'Clé API Tavus';
