$string['settings:talking_avatar_tavus_persona_id'] = 'Identifiant de réplique Tavus';
$string['settings:talking_avatar_tavus_persona_id_desc'] = 'Identifiant de la réplique (l\'apparence entraînée) avec laquelle vous voulez que [[tutorshort]] converse. Combinez-le avec un identifiant de persona en l\'ajoutant au champ de clé API si nécessaire ; [[tutorshort]] transmettra <code>persona_id</code>.';
$string['settings:talking_avatar_synthesia_api_key'] = 'Clé API Synthesia';
$string['settings:talking_avatar_synthesia_api_key_desc'] = 'Clé API issue de <a href="https://app.synthesia.io/#/account/api" target="_blank" rel="noopener">Synthesia → Compte → API</a>. Envoyée dans l\'en-tête <code>Authorization</code> (Synthesia accepte la clé brute).';
