$string['talking_avatar:disabled'] = 'L\'avatar parlant n\'est pas activé pour ce cours.';
$string['talking_avatar:unconfigured'] = 'L\'avatar parlant est activé mais aucun fournisseur n\'a été configuré. Un administrateur doit choisir un fournisseur et fournir les identifiants dans les paramètres du plugin.';
