$string['talking_avatar:bundle_required'] = 'La visionneuse d\'avatar parlant nécessite que le bundle CDN de [[tutorshort]] soit configuré. Demandez à un administrateur de définir l\'URL du bundle CDN dans les paramètres du plugin.';
$string['talking_avatar:open'] = 'Ouvrir l\'avatar';
$string['talking_avatar:close'] = 'Fermer l\'avatar';
$string['settings:avatar_rate_card_overrides'] = 'Remplacements de la grille tarifaire des avatars (JSON)';
$string['settings:avatar_rate_card_overrides_desc'] = 'Objet JSON indexé par fournisseur d\'avatar, avec un tarif unique en USD par minute. Remplace le tarif fourni pour ce fournisseur. Exemple : <pre>{ "did": 0.18, "heygen": 0.40, "tavus": 0.25 }</pre> Vide = utiliser les valeurs par défaut livrées avec la v4.10.0 : D-ID 0,30 $/min, HeyGen 0,50 $/min, Tavus 0,30 $/min, Synthesia 0,40 $/min. Renseignez ici votre tarif contractuel pour que le tableau de bord d\'analyses reflète le coût réel de l\'établissement.';
$string['settings:talking_avatar_did_webhook_secret'] = 'Secret de signature du webhook D-ID';
$string['settings:talking_avatar_did_webhook_secret_desc'] = 'Facultatif. Lorsqu\'il est défini, D-ID peut envoyer par POST les événements de fin de session vers <code>{wwwroot}/local/ai_course_assistant/talking_avatar_webhook.php?provider=did</code>, signés avec ce secret dans <code>X-DID-Signature</code> (HMAC-SHA256 hexadécimal). Les lignes issues du webhook priment sur le signal de présence du frontend. Vide = gestionnaire désactivé, le signal de présence et le balayage horaire gèrent seuls la fin de session.';
$string['settings:talking_avatar_heygen_webhook_secret'] = 'Secret de signature du webhook HeyGen';
$string['settings:talking_avatar_heygen_webhook_secret_desc'] = 'Facultatif. Lorsqu\'il est défini, HeyGen peut envoyer par POST les événements de fin de session signés avec ce secret dans <code>X-HeyGen-Signature</code> (HMAC-SHA256 hexadécimal). Vide = gestionnaire désactivé.';
$string['settings:talking_avatar_tavus_webhook_secret'] = 'Secret de signature du webhook Tavus';
$string['settings:talking_avatar_tavus_webhook_secret_desc'] = 'Facultatif. Lorsqu\'il est défini, Tavus peut envoyer par POST les événements de fin de conversation signés avec ce secret dans <code>X-Tavus-Signature</code> (HMAC-SHA256 hexadécimal). Vide = gestionnaire désactivé.';
$string['settings:talking_avatar_synthesia_webhook_secret'] = 'Secret de signature du webhook Synthesia';
$string['settings:talking_avatar_synthesia_webhook_secret_desc'] = 'Facultatif. Lorsqu\'il est défini, Synthesia peut envoyer par POST les événements de fin de session d\'agent signés avec ce secret dans <code>X-Synthesia-Signature</code> (HMAC-SHA256 hexadécimal). Vide = gestionnaire désactivé.';
$string['analytics:avatar_cost_heading'] = 'Utilisation de l\'avatar parlant';
$string['analytics:avatar_cost_provider'] = 'Fournisseur';
$string['analytics:avatar_cost_sessions'] = 'Sessions';
$string['analytics:avatar_cost_minutes'] = 'Minutes';
$string['analytics:avatar_cost_rate'] = 'Tarif à la minute';
$string['analytics:avatar_cost_total'] = 'Total estimé';
$string['analytics:avatar_cost_empty'] = 'Aucune session d\'avatar parlant sur la période sélectionnée.';
$string['task:sweep_avatar_sessions'] = 'Fermer les sessions d\'avatar parlant inactives';
$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'Prompt verbeux du mode socratique';
$string['settings:socratic_verbose_desc'] = 'Lorsque cette option est activée, les cours en mode socratique reçoivent la directive complète "à faire / à ne pas faire" d\'environ 600 jetons ajoutée à l\'origine en v3.9.30. Lorsqu\'elle est désactivée (par défaut), ils reçoivent une directive d\'une seule ligne que les modèles hébergés modernes suivent de façon fiable et qui économise environ 600 jetons par tour. Activez-la si un cours fonctionne sur un modèle auto-hébergé plus faible qui a besoin de cet étayage explicite.';
$string['settings:prompt_budget_chars'] = 'Budget de caractères du prompt système';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'Limite de contenu de la page courante (caractères)';
$string['settings:current_page_content_maxchars_desc'] = 'Nombre maximal de caractères du texte de la page actuelle injectés dans l\'invite système en tant que section « Contenu de la page actuelle », lorsque le RAG est désactivé. La valeur par défaut de 8,000 ancre bien les questions propres à la page tout en laissant du budget pour la structure et les instructions. (Avec le RAG activé, la page est plutôt ancrée par ses propres fragments les plus pertinents, biaisés vers la page actuelle, de sorte que cette limite ne s\'applique pas.) Une page très longue est tronquée par le début à ce nombre de caractères, si bien que la fin d\'une page extrêmement longue pourrait ne pas être citée ; activer le RAG évite cela. Les sites soucieux des coûts peuvent réduire cette valeur (p. ex. 3,000-4,000). Limité à la plage 500-8,000. Indépendant de <code>prompt_budget_chars</code> : ceci ne limite que la section de la page ; le budget limite l\'ensemble de l\'invite.';
$string['settings:prompt_verbosity'] = 'Verbosité du prompt';
$string['settings:prompt_verbosity_desc'] = 'Verbosité par défaut des blocs d\'instructions (mode socratique, ressources externes). Concis (par défaut) est ce que les modèles hébergés modernes suivent de façon fiable ; standard ajoute un étayage explicite pour les modèles de milieu de gamme ; verbeux conserve les consignes lourdes de l\'époque v3.9.30 pour les modèles auto-hébergés plus faibles. Un remplacement par cours est disponible via <code>prompt_verbosity_course_&lt;id&gt;</code>.';
$string['settings:prompt_verbosity_concise'] = 'Concis (recommandé pour les modèles hébergés)';
$string['settings:prompt_verbosity_standard'] = 'Standard';
$string['settings:prompt_verbosity_verbose'] = 'Verbeux (pour les modèles auto-hébergés plus faibles)';
$string['settings:prompt_metrics_enabled'] = 'Enregistrer les métriques de prompt par section';
$string['settings:prompt_metrics_enabled_desc'] = 'Lorsque cette option est activée (par défaut), chaque tour de conversation écrit une ligne JSON par prompt assemblé dans <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code>, avec le nombre de caractères par catégorie. Les 7 derniers jours sont conservés. La page d\'administration des métriques les agrège pour la recommandation de budget. Aucune donnée personnelle n\'est enregistrée — uniquement la taille des sections. Désactivez cette option si votre établissement préfère n\'avoir aucun fichier de métriques.';
$string['settings:prompt_budget_auto_tune'] = 'Ajustement automatique quotidien du budget du prompt système (obsolète)';
$string['settings:prompt_budget_auto_tune_desc'] = 'Obsolète. Sans effet à moins que le mode de budget ci-dessus soit réglé sur <strong>Fixe</strong>. Une tâche quotidienne déduisait le budget de caractères en surveillant les troncatures et en poursuivant le plus grand prompt observé. Déduire le budget de la fenêtre de contexte du modèle fait mieux : cela ne peut pas osciller et ne demande aucune donnée de démarrage. Les deux entraient de plus en conflit, car la tâche écrit le budget de caractères et toute valeur autre que celle par défaut désactive le budget déduit. Laissez ceci désactivé ; il sera supprimé dans une version future. La recommandation apparaît toujours sur la page <a href="/local/ai_course_assistant/prompt_metrics.php">Métriques du prompt</a>.';
