// v5.3.0: Empathetic communications + carryover memory (English fallback).
$string['task:milestone_check'] = 'Envoyer les e-mails quotidiens de réflexion sur les jalons (v5.3.0)';
$string['task:struggle_signal_review'] = 'Intégrer les signaux de difficulté à la mémoire privée de l\'apprenant (v5.3.0)';
$string['empathy:title'] = 'Communications empathiques et mémoire de continuité (v5.3.0)';
$string['empathy:desc'] = 'Trois fonctions coordonnées qui font davantage de [[tutorshort]] un coach à l\'écoute. Les objectifs recueillent la raison pour laquelle l\'apprenant est là. La mémoire de continuité retient ce qui a été difficile auparavant, afin que [[tutorshort]] puisse proposer un autre angle. Les jalons célèbrent les séries et les cours terminés par e-mail. Chaque fonction dispose d\'un interrupteur d\'arrêt indépendant et d\'une adhésion volontaire de l\'apprenant. Les signaux de difficulté ne quittent jamais le chat : aucun e-mail n\'est jamais envoyé au sujet d\'une session difficile.';
$string['empathy:outreach_master_enabled'] = 'Interrupteur d\'arrêt principal des envois';
$string['empathy:outreach_master_enabled_desc'] = 'Désactivé par défaut sur une installation neuve. Lorsqu\'il est désactivé, AUCUN e-mail empathique, quel qu\'il soit, n\'est jamais envoyé, quels que soient les interrupteurs par fonction ci-dessous. Activez-le une fois que vous avez examiné les valeurs par défaut de chaque fonction et le parcours de consentement de l\'apprenant.';
$string['empathy:goals_enabled'] = 'Activer les conversations sur les objectifs de carrière';
$string['empathy:goals_enabled_desc'] = 'Permet aux apprenants de donner spontanément deux réponses courtes (pourquoi ils sont là, ce qu\'ils veulent devenir) qui alimentent la personnalisation. Uniquement dans le chat ; aucun e-mail. Peut rester activé sans risque.';
$string['empathy:milestones_enabled'] = 'Activer les e-mails de réflexion sur les jalons';
$string['empathy:milestones_enabled_desc'] = 'Envoie un court e-mail chaleureux lorsqu\'un apprenant atteint une série de 7 jours, une série de 30 jours ou termine le cours. Nécessite l\'interrupteur principal ci-dessus ainsi que le consentement de chaque apprenant. Plafond strict d\'un e-mail par apprenant tous les 7 jours, tous canaux confondus.';
$string['empathy:memory_enabled'] = 'Activer la mémoire de personnalisation persistante';
$string['empathy:memory_enabled_desc'] = 'Permet à [[tutorshort]] de conserver, d\'une session à l\'autre, de petites notes privées sur ce qui a été difficile pour un apprenant, afin que la réponse suivante puisse proposer un autre angle. Volume limité (5 notes au maximum par apprenant et par cours, durée de vie de 90 jours). Modifiable par l\'apprenant. Jamais visible par les enseignants.';
$string['empathy:struggle_enabled'] = 'Activer le classificateur de difficulté';
$string['empathy:struggle_enabled_desc'] = 'Désactivé par défaut. Permet à [[tutorshort]] de détecter une frustration persistante sur plusieurs échanges et d\'enregistrer discrètement une note de blocage dans la mémoire de continuité ci-dessus. Le résultat reste uniquement dans le chat ; aucun e-mail n\'est jamais envoyé au sujet d\'une session difficile. Les données de signal sont purgées automatiquement au bout de 7 jours.';
$string['empathy:outreach_dryrun'] = 'Simulation des envois (journaliser sans envoyer)';
$string['empathy:outreach_dryrun_desc'] = 'Lorsque cette option est activée, la tâche planifiée des jalons écrit des lignes d\'audit comme si elle avait envoyé des e-mails, mais n\'envoie réellement d\'e-mail à personne. Utilisez-la sur une installation neuve pour vérifier la logique de délai d\'attente et de consentement avant la mise en service.';
