$string['privacy:metadata:email_optout:userid'] = 'L\'utilisateur Moodle auquel appartient la désinscription, lorsqu\'il est connu.';
$string['chat:consent_scroll_hint'] = 'Veuillez faire défiler jusqu\'en bas pour lire l\'intégralité de l\'avis avant de continuer.';
$string['settings:rag_min_similarity'] = 'Pertinence minimale (cosinus)';
$string['settings:rag_min_similarity_desc'] = 'Écarte les fragments récupérés dont la similarité cosinus avec la question est inférieure à cette valeur, afin qu\'une question hors sujet ou peu fournie injecte moins de passages (voire aucun) au lieu de toujours compléter jusqu\'à Top-K avec des correspondances faibles. Plage de 0 à 1 ; 0 désactive le filtre. La bonne valeur dépend du modèle d\'embedding : 0.25 convient à text-embedding-3-small. Augmentez-la pour être plus strict (moins de contexte, plus centré sur le sujet), abaissez-la pour être plus permissif.';
$string['settings:rag_currentpage_boost'] = 'Bonus page actuelle';
$string['settings:rag_currentpage_boost_desc'] = 'Un petit bonus ajouté au score de pertinence des fragments de la page que l\'apprenant consulte actuellement, afin que des questions comme « explique ceci » privilégient la page visible lorsque les scores sont proches. Affecte uniquement l\'ordre : il ne force pas un fragment de page non pertinent à passer le filtre de pertinence minimale. Réglez sur 0 pour désactiver.';
$string['settings:history_mode'] = 'Mode de sélection de l\'historique';
$string['settings:history_mode_desc'] = 'Comment les tours de conversation passés sont choisis avant d\'être envoyés au modèle. <strong>Sémantique</strong> ne conserve que les tours récents pertinents pour la question actuelle (et toujours le dernier échange), afin qu\'un tour antérieur obsolète et hors sujet ne gonfle pas le coût ni ne détourne la réponse ; il effectue un appel d\'embedding supplémentaire par message. <strong>Récence</strong> conserve les derniers paires « Historique de conversation maximal » quelle que soit leur pertinence (le comportement historique, sans appel supplémentaire). Si l\'embedding n\'est pas disponible, le mode sémantique bascule automatiquement vers la récence.';
$string['settings:history_mode_semantic'] = 'Sémantique (tours récents pertinents)';
$string['settings:history_mode_recency'] = 'Récence (N dernières paires)';
$string['settings:history_semantic_minscore'] = 'Seuil de pertinence de l\'historique (cosinus)';
$string['settings:history_semantic_minscore_desc'] = 'En mode d\'historique sémantique, un tour antérieur n\'est conservé que si sa similarité avec la question actuelle est au moins égale à cette valeur (le dernier échange est toujours conservé). Plage de 0 à 1 ; dépend du modèle. Augmentez pour être plus strict (moins d\'historique), abaissez pour en conserver davantage.';
$string['settings:history_candidates'] = 'Fenêtre de candidats de l\'historique';
$string['settings:history_candidates_desc'] = 'En mode d\'historique sémantique, seules les paires les plus récentes, jusqu\'à ce nombre, sont évaluées en pertinence (une limite de coût). Les paires plus anciennes que cette fenêtre ne sont pas envoyées. Maintenez cette valeur égale ou supérieure à « Historique de conversation maximal ».';

// v5.11.0 - v6.2.0 strings (added 2026-06-10).
$string['settings:embed_provider_voyage'] = 'Voyage AI (voyage-3.5 — recommandé ; +4 MTEB vs OpenAI 3-small, 4x contexte, multilingue)';
$string['settings:rerank_heading'] = 'RAG : Récupération en deux étapes (reclassement)';
$string['settings:rerank_heading_desc'] = 'Deuxième étape de récupération optionnelle : la similarité cosinus sélectionne les N meilleurs fragments candidats (50 par défaut), puis un reclasseur à encodeur croisé note chaque paire (requête, fragment) et les meilleurs K entrent dans le prompt. Désactivé par défaut ; repasse à la similarité cosinus simple si le reclasseur n\'est pas configuré ou échoue.';
$string['settings:rerank_enabled'] = 'Récupération en deux étapes (Voyage rerank-2.5)';
$string['settings:rerank_enabled_desc'] = 'Lorsqu\'activé, la récupération RAG devient en deux étapes : la similarité cosinus renvoie les N meilleurs candidats (50 par défaut), puis l\'encodeur croisé Voyage rerank-2.5 note chacun et les K meilleurs entrent dans le prompt. Améliorations publiées : +15 Recall@10 entreprise, +39 % NDCG BEIR. ~0,05 $/MTok de facturation. Nécessite <code>rerank_apikey</code> ci-dessous ; revient gracieusement à la similarité cosinus simple si le reclassement échoue ou n\'est pas configuré.';
$string['settings:rerank_apikey'] = 'Clé API de reclassement';
$string['settings:rerank_apikey_desc'] = 'Clé API Voyage AI pour rerank-2.5. Laissez vide pour réutiliser la clé API d\'embedding ci-dessus (les déploiements Voyage typiques partagent une seule clé entre embed et rerank).';
$string['settings:rerank_model'] = 'Modèle de reclassement';
$string['settings:rerank_model_desc'] = 'Par défaut <code>rerank-2.5</code>. Des modèles de reclassement Voyage plus récents peuvent être spécifiés ici.';
$string['settings:rerank_apibaseurl'] = 'URL de base de l\'API de reclassement';
$string['settings:rerank_apibaseurl_desc'] = 'Remplace l\'URL de base de reclassement Voyage. Laissez vide pour utiliser l\'URL de base de l\'API d\'embedding ci-dessus, ou la valeur par défaut de Voyage (<code>https://api.voyageai.com/v1</code>).';
$string['settings:rerank_candidates'] = 'Fenêtre de candidats de reclassement';
$string['settings:rerank_candidates_desc'] = 'Nombre de candidats cosinus top-N transmis à l\'étape de reclassement. Par défaut 20. Mesuré sur 1 008 requêtes : 20 égale 30 en rappel (R@3 89,0 % contre 89,3 %) pour un tiers de coût en moins, et 50 coûte 2,5 fois plus sans gain mesurable. En dessous de 10, le rappel se dégrade. Le coût augmente linéairement avec cette valeur.';
$string['settings:stt_selfhosted_heading'] = 'Transcription auto-hébergée (Whisper)';
$string['settings:stt_selfhosted_heading_desc'] = 'Exécutez la conversion parole-texte sur votre propre matériel à zéro coût par minute. Pointez [[tutorshort]] vers n\'importe quel serveur de transcription compatible OpenAI : Docker <code>whisper-server</code>, <code>speaches</code> (faster-whisper) ou serveur <code>whisper.cpp</code>. Lorsqu\'une URL de serveur est définie ici, elle devient le chemin STT par défaut ; sélectionnez un fournisseur payant dans Fournisseur STT actif ci-dessus pour le remplacer. Si le serveur est sur un réseau privé ou en http simple, ajoutez également son hôte à la liste blanche des points de terminaison SSRF approuvés dans la section Sécurité.';
$string['settings:stt_selfhosted_url'] = 'URL du serveur STT auto-hébergé';
$string['settings:stt_selfhosted_url_desc'] = 'URL de base du serveur de transcription compatible OpenAI, par exemple <code>http://10.0.0.5:8000</code>. [[tutorshort]] ajoute <code>/v1/audio/transcriptions</code> automatiquement ; un chemin de point de terminaison complet est également accepté. Laissez vide pour désactiver le STT auto-hébergé.';
$string['settings:stt_selfhosted_model'] = 'Modèle STT auto-hébergé';
$string['settings:stt_selfhosted_model_desc'] = 'Nom du modèle transmis au serveur, correspondant au modèle Whisper chargé — par exemple <code>Systran/faster-whisper-small</code> pour speaches ou <code>large-v3</code>. Laissez vide pour envoyer <code>whisper-1</code>, que la plupart des serveurs auto-hébergés acceptent ou ignorent.';
$string['settings:stt_selfhosted_apikey'] = 'Clé API STT auto-hébergé';
$string['settings:stt_selfhosted_apikey_desc'] = 'Optionnel. La plupart des serveurs auto-hébergés n\'ont pas besoin de clé sur un réseau de confiance ; définissez-la seulement si votre serveur requiert un token bearer.';
$string['emergency:title'] = 'Contrôles d\'urgence [[tutorshort]]';
$string['emergency:page_warning'] = 'Ces interrupteurs prennent effet immédiatement pour tous les apprenants du site. Chaque action écrit une ligne d\'audit. Les interrupteurs granulaires laissent le reste de [[tutorshort]] fonctionner ; le kill maître supprime entièrement le widget.';
$string['emergency:back_to_settings'] = 'Paramètres [[tutorshort]]';
$string['emergency:state_disabled'] = 'DÉSACTIVÉ';
$string['emergency:state_active'] = 'Actif';
$string['emergency:confirm_label'] = 'Je comprends que cela affecte immédiatement tous les apprenants';
$string['emergency:confirm_required'] = 'Veuillez cocher la case de confirmation avant de désactiver un sous-système.';
$string['emergency:reason_placeholder'] = 'Raison (enregistrée dans le journal d\'audit)';
$string['emergency:disable_button'] = 'Désactiver';
$string['emergency:restore_button'] = 'Restaurer';
$string['emergency:disabled_notice'] = 'Sous-système "{$a->flag}" désactivé. Configuration modifiée : {$a->touched}';
$string['emergency:restored_notice'] = 'Sous-système "{$a->flag}" restauré. Configuration modifiée : {$a->touched}';
$string['emergency:cli_reference'] = 'Les mêmes contrôles sont disponibles depuis le shell d\'astreinte :';
$string['emergency:flag_chat'] = 'Chat';
$string['emergency:flag_chat_desc'] = 'Arrête tous les appels d\'IA de [[tutorshort]] — chat, quiz, cartes mémoire et notation — pour les apprenants, les administrateurs et les tâches planifiées. Le widget continue de s\'afficher et les apprenants voient un bref message de pause. L\'autotest du backend et la vérification d\'état restent disponibles afin de contrôler le fournisseur avant de rétablir.';
$string['emergency:flag_voice'] = 'Voix';
$string['emergency:flag_voice_desc'] = 'Efface le fournisseur de voix temps réel actif (mis en cache pour une restauration exacte). Le chat texte continue de fonctionner.';
$string['emergency:flag_rag'] = 'RAG';
$string['emergency:flag_rag_desc'] = 'Désactive la récupération et l\'indexation. Le chat continue sans ancrage dans le contenu du cours.';
$string['emergency:flag_outreach'] = 'Communication';
$string['emergency:flag_outreach_desc'] = 'Arrête les e-mails de résumé, d\'étape et de rappel. Le chat n\'est pas affecté.';
$string['emergency:flag_all'] = 'KILL MAÎTRE';
$string['emergency:flag_all_desc'] = 'Désactive l\'ensemble du plugin : widget supprimé de toutes les pages, tâches planifiées arrêtées, voix effacée, RAG désactivé, communication désactivée. L\'interrupteur le plus puissant — à utiliser pour un incident de sécurité ou quand [[tutorshort]] doit être mis hors ligne immédiatement.';
$string['emergency:settings_link'] = 'Contrôles d\'urgence';
$string['emergency:settings_link_desc'] = 'Interrupteurs kill par sous-système (chat / voix / RAG / communication / maître) avec journalisation d\'audit — l\'équivalent web de <code>admin/cli/emergency_disable.php</code>. Ouvrir <a href="{$a}">Contrôles d\'urgence [[tutorshort]]</a>.';
$string['email_unsubscribe:done_title'] = 'Désinscription effectuée';
$string['email_unsubscribe:done_body'] = 'C\'est fait — {$a->email} ne recevra plus ce type d\'e-mail de la part de {$a->product}. Si vous changez d\'avis, demandez à un administrateur {$a->product} de réactiver l\'abonnement, ou envoyez un nouvel opt-in via la page d\'administration des destinataires [[tutorshort]].';
$string['email_unsubscribe:invalid_title'] = 'Le lien de désinscription n\'est plus valide';
$string['email_unsubscribe:invalid_body'] = 'Ce lien de désinscription a expiré ou est malformé. Recherchez un e-mail plus récent de notre part, ou contactez un administrateur du site pour être retiré manuellement.';
$string['settings:prompt_proportions_heading'] = 'Proportions des sections du prompt (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'Allouez le budget du prompt système sur quatre compartiments : sécurité + identité, structure du cours, contenu du cours et page actuelle. Les pondérations sont des pourcentages dont la somme est 100. Les valeurs par défaut calibrées empiriquement (10 / 10 / 40 / 40) proviennent du benchmark de calibrage des pondérations v5.6.0 ; laisser la zone de texte vide utilise ces valeurs par défaut. Le boost automatique ajuste l\'allocation à chaque tour selon qu\'une page spécifique est dans la portée.';
$string['settings:prompt_section_weights'] = 'Pondérations de section de base (JSON)';
$string['settings:prompt_section_weights_desc'] = 'Objet JSON optionnel associant chaque compartiment à un pourcentage. Laissez vide pour utiliser les valeurs par défaut du benchmark (10 / 10 / 40 / 40). Exemple : <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. Les pondérations doivent totaliser 100 (±5 %). <code>safety_identity</code> a un plancher de 10 % pour que la résistance aux jailbreaks et les marqueurs de format de sortie atterrissent toujours en totalité. <code>current_page + course_content</code> doit représenter au moins 40 % pour que le modèle dispose de matière substantielle sur laquelle s\'appuyer. Les valeurs hors plage reviennent silencieusement aux valeurs par défaut du benchmark ; les administrateurs doivent valider en consultant le journal de débogage des prompts après sauvegarde.';
$string['settings:prompt_context_boost_mode'] = 'Mode de boost de contexte';
$string['settings:prompt_context_boost_mode_desc'] = 'Ajustement automatique qui déplace le poids vers la section de page actuelle quand une page spécifique est dans la portée, et vers le contenu du cours quand aucune page n\'est sélectionnée. <strong>page_focus</strong> (par défaut) déplace environ 15 points de pondération. <strong>aggressive</strong> déplace 25 points et est préférable quand les apprenants posent systématiquement des questions spécifiques à une page. <strong>off</strong> désactive le boost ; les pondérations de base définies par l\'administrateur s\'appliquent à chaque tour quel que soit le contexte de page.';
$string['settings:prompt_context_boost_off'] = 'Désactivé (utiliser les pondérations de base à chaque tour)';
$string['settings:prompt_context_boost_page_focus'] = 'Focus page (par défaut, déplacement de ~15 points)';
$string['settings:prompt_context_boost_aggressive'] = 'Agressif (~25 points de déplacement)';
$string['settings:prompt_section_weights_coach'] = 'Remplacement en mode coach (JSON, optionnel)';
$string['settings:prompt_section_weights_coach_desc'] = 'Objet JSON optionnel remplaçant les pondérations de section de base spécifiquement lors du mode coach de quiz noté (quand <code>quizmode=coach</code>). Utile pour forcer une allocation <code>current_page</code> plus lourde lors des quiz sans affecter le chat normal. Laissez vide pour hériter des pondérations de base. Mêmes règles de validation que le paramètre de base.';
$string['prompt_debug_view:title'] = 'Visionneuse du journal de débogage des prompts';
$string['prompt_debug_view:subtitle'] = 'Prompt système assemblé par tour + ventilation par section + historique des conversations + message utilisateur actuel + métadonnées des pièces jointes, exactement tels que le modèle les a reçus. Utilisez ceci pour vérifier si une section comme Contenu de la page actuelle a bien été incluse dans le prompt et pour déboguer les problèmes de qualité des réponses sans connexion SSH au serveur.';
$string['prompt_debug_view:disabled'] = 'La journalisation de débogage des prompts est actuellement DÉSACTIVÉE. Aucune nouvelle entrée ne sera écrite tant qu\'elle n\'est pas activée.';
$string['prompt_debug_view:enable_link'] = 'Ouvrez les paramètres du plugin pour activer « Journaliser le prompt système assemblé dans un fichier ».';
$string['prompt_debug_view:no_log_yet'] = 'Pas encore de fichier journal. Envoyez au moins un tour de chat après avoir activé le journal de débogage ; le fichier est créé lors du premier enregistrement.';
$string['prompt_debug_view:empty'] = 'Le fichier journal existe mais est vide. Envoyez un tour de chat et actualisez.';
$string['prompt_debug_view:file_status'] = 'Taille du fichier journal';
$string['prompt_debug_view:showing'] = 'Affichage des entrées les plus récentes (les plus récentes en premier), limite';
$string['prompt_debug_view:total'] = 'Prompt total';
$string['prompt_debug_view:budget'] = 'Budget au moment de la capture';
$string['prompt_debug_view:sections'] = 'Sections (par catégorie)';
$string['prompt_debug_view:assembled_prompt'] = 'Prompt système assemblé';
$string['prompt_debug_view:history'] = 'Historique de conversation envoyé au modèle';
$string['prompt_debug_view:current_message'] = 'Message utilisateur actuel';
$string['prompt_debug_view:attachment'] = 'Métadonnées de la pièce jointe';
$string['prompt_debug_view:show_more'] = 'Afficher plus d\'entrées';
$string['settings:mastery_classifier_provider'] = 'Fournisseur du classificateur';
$string['settings:mastery_classifier_provider_desc'] = 'Identifiant du fournisseur utilisé pour le classificateur de maîtrise par tour. Laissez vide pour hériter du fournisseur d\'IA par défaut. La valeur par défaut <code>openai</code> est associée au modèle classificateur <code>gpt-4o-mini</code> ci-dessous — l\'option TIER 1 la moins coûteuse pour la classification à sortie structurée (~220 $/mois d\'économies à 100 000 MAU vs le tier chat). Quand défini, la ligne dans Fournisseurs de comparaison avec cet identifiant de fournisseur fournit la clé API, l\'URL de base et la température.';
$string['settings:premium_escalation_heading'] = 'Niveau d\'escalade premium (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Routage optionnel par tour vers un modèle premium (Claude Opus 4.8 par défaut) pour les prompts où le tier chat de base peine visiblement — typiquement les mathématiques multi-étapes, CS et le raisonnement scientifique. Résolu par le bake-off A.10 du 09/06/2026 : Opus 4.8 a remporté 14,97/15 contre 12,68/15 pour gpt-4o sur les prompts difficiles. Deux chemins de déclenchement : correspondances regex sur le message utilisateur, OU une liste d\'autorisation de cours qui escalade à chaque tour. Désactivé par défaut. À ~5 % d\'escalade, attendez ~700 $/mois à 100 000 [[unishort]] MAU en plus des dépenses de chat de base.';
$string['settings:premium_escalation_enabled'] = 'Activer le routage d\'escalade premium';
$string['settings:premium_escalation_enabled_desc'] = 'Lorsqu\'activé, le routeur par tour vérifie la liste de regex de déclenchement et la liste d\'autorisation de cours pour chaque appel de chat ; les tours correspondants sont acheminés vers le fournisseur premium. Revient au fournisseur de base si la ligne premium est manquante ou ne peut pas être instanciée. Les remplacements du sélecteur LLM administrateur l\'emportent toujours quoi qu\'il arrive.';
$string['settings:premium_escalation_provider'] = 'Fournisseur premium';
$string['settings:premium_escalation_provider_desc'] = 'Identifiant du fournisseur pour router les appels premium. Doit correspondre à une ligne dans Fournisseurs de comparaison (pour que la clé API, l\'URL de base et la température proviennent du même endroit que les administrateurs gèrent déjà). Par défaut <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Modèle premium';
$string['settings:premium_escalation_model_desc'] = 'Nom du modèle transmis au fournisseur premium. Par défaut <code>claude-sonnet-5</code> conformément au verdict du bake-off A.10.';
$string['settings:premium_escalation_triggers'] = 'Regex de déclenchement premium';
$string['settings:premium_escalation_triggers_desc'] = 'Un regex PCRE par ligne (sans délimiteurs ; la correspondance insensible à la casse est appliquée automatiquement). Les lignes commençant par # sont des commentaires. Laissez vide pour utiliser l\'ensemble par défaut sélectionné du bake-off A.10 (marqueurs STEM multi-étapes : "derive", "prove that", "step by step", LaTeX math, blocs de code délimités, big-O, intégrales, optimisation, etc.).';
$string['settings:premium_escalation_course_tags'] = 'Liste d\'autorisation de cours premium';
$string['settings:premium_escalation_course_tags_desc'] = 'Un nom court de cours ou préfixe d\'idnumber par ligne. Chaque tour dans un cours correspondant est automatiquement escaladé quel que soit le regex du message (à utiliser pour les cours à forte composante STEM où l\'escalade doit être le comportement par défaut). La correspondance est insensible à la casse par préfixe — "MATH" correspond à MATH121, MATH205, etc.';
$string['settings:spend_cap_per_course_default'] = 'Plafond de dépenses par cours par défaut (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Plafond défensif appliqué à chaque cours qui n\'a pas son propre plafond de dépenses par cours configuré. Définissez par exemple <code>30</code> pour limiter les dépenses mensuelles de tout cours individuel à 30 $ sans avoir à régler les cours un par un. <code>0</code> = pas de plafond par défaut (seuls les plafonds au niveau du site et les remplacements par cours s\'appliquent). Lorsqu\'un cours dépasse 80 % / 95 % / 100 % de ce plafond, le pipeline d\'alertes spend-guard existant envoie la notification administrateur (liste des destinataires : <code>spend_notify_emails</code>, revenant aux administrateurs du site). Un cours spécifique peut toujours relever son propre plafond en définissant un remplacement par cours plus élevé.';
$string['settings:cost_anomaly_heading'] = 'Détecteur d\'anomalie de coûts (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Tâche planifiée quotidienne (<code>cost_anomaly_check</code>) qui compare les dépenses [[tutorshort]] du site d\'aujourd\'hui à la médiane glissante sur 7 jours. Envoie un e-mail à la liste de destinataires <code>spend_notify_emails</code> (revenant aux administrateurs du site) quand aujourd\'hui dépasse le multiplicateur configuré × la médiane. Détecte trois modes de défaillance que les seuils 80 % / 95 % / 100 % du plafond de dépenses existant ne détectent pas : (1) cours emballé où le plafond absolu n\'est pas franchi mais un seul cours génère soudainement 10 fois son volume habituel, (2) activation accidentelle du tier premium, (3) mauvais routage fournisseur. Désactivé par défaut ; l\'équivalent interne à [[tutorshort]] de la requête Redash de <code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>.';
$string['settings:cost_anomaly_enabled'] = 'Activer le détecteur d\'anomalie de coûts';
$string['settings:cost_anomaly_enabled_desc'] = 'Lorsqu\'activé, la tâche planifiée quotidienne évalue les dépenses d\'aujourd\'hui par rapport à la médiane glissante sur 7 jours et envoie un e-mail aux administrateurs en cas d\'anomalie. Les 7 premiers jours après l\'activation produisent un statut <code>insufficient_history</code> (pas encore de référence historique) et n\'émettent jamais d\'alerte. Idempotent par jour : un drapeau dans <code>config_plugins</code> empêche les e-mails répétés si cron s\'exécute plusieurs fois.';
$string['settings:cost_anomaly_multiplier'] = 'Multiplicateur d\'anomalie';
$string['settings:cost_anomaly_multiplier_desc'] = 'Les dépenses d\'aujourd\'hui doivent dépasser ce multiplicateur × la médiane sur 7 jours pour déclencher une alerte. Par défaut <code>2.0</code>. Abaissez à <code>1.5</code> pour des avertissements plus précoces (plus de faux positifs lors des pics d\'inscription). Augmentez à <code>3.0</code> si l\'utilisation de [[unishort]] est suffisamment irrégulière pour que des pics de 2x soient habituels.';
$string['task:cost_anomaly_check'] = 'Vérification des anomalies de coûts [[tutorshort]] (quotidienne)';

// v6.4.0 signed policy bundle strings (added 2026-06-11).
$string['settings:policy_bundle_heading'] = 'Pack de politiques signé (mises à jour du comportement à distance)';
$string['settings:policy_bundle_heading_desc'] = 'Appliquez des paramètres de comportement (invites, routage, déclencheurs d\'escalade, réglage RAG, politique de dépenses) depuis un fichier JSON signé cryptographiquement sans déploiement de code. Une tâche planifiée quotidienne récupère l\'URL du pack, vérifie sa signature Ed25519 par rapport à la clé publique ci-dessous et applique les paramètres uniquement si chaque clé figure dans la liste d\'autorisation intégrée et si la version du pack est plus récente que la dernière appliquée. Les clés API, les URL, les webhooks et les paramètres de sécurité ne peuvent jamais être définis par un pack. Créez et signez des packs avec <code>admin/cli/policy_bundle_tool.php</code> (keygen, sign, verify, status, sync).';
$string['settings:policy_bundle_enabled'] = 'Activer la synchronisation du pack de politiques';
$string['settings:policy_bundle_enabled_desc'] = 'Lorsqu\'activée, la tâche quotidienne récupère et applique les packs signés. Désactivée par défaut. La désactivation arrête immédiatement toutes les synchronisations ; les paramètres déjà appliqués conservent leurs valeurs.';
$string['settings:policy_bundle_url'] = 'URL du pack de politiques';
$string['settings:policy_bundle_url_desc'] = 'URL HTTPS du JSON du pack signé (par exemple un objet S3 ou GitHub raw URL). L\'URL est soumise à la même validation SSRF que les points de terminaison des fournisseurs d\'IA ; les hôtes de réseau privé ou plain-http nécessitent une entrée dans la liste d\'autorisation des points de terminaison SSRF de confiance.';
$string['settings:policy_bundle_pubkey'] = 'Clé publique du pack de politiques';
