$string['settings:active_learners_enabled'] = 'Afficher l\'indicateur d\'apprenants actifs';
$string['settings:active_learners_enabled_desc'] = 'Affiche dans le volet de discussion le nombre d\'autres personnes en train d\'étudier. C\'est un encouragement social plutôt qu\'une fonction pédagogique, et cela interroge le serveur une fois par minute pour chaque volet ouvert : désactivé par défaut. L\'indicateur n\'apparaît que si au moins deux autres personnes sont actives.';

$string['task:unanswered_check'] = '[[tutorshort]] vérification des questions sans réponse';
$string['settings:unanswered_check_enabled'] = 'Alerter quand des questions restent sans réponse';
$string['settings:unanswered_check_enabled_desc'] = 'Envoie un courriel aux destinataires des notifications de dépense lorsque les apprenants posent des questions à [[tutorshort]] sans obtenir de réponse. Le détecteur d\'anomalies de coût ne se déclenche que si la dépense <em>augmente</em> : un fournisseur qui rejette tous les appels ne coûte rien et ne déclenche aucune alerte. Ceci surveille le rapport questions/réponses, qui tombe à zéro dès qu\'un fournisseur tombe en panne. Si la liste de notification est vide, les administrateurs du site sont utilisés.';
$string['settings:unanswered_window_hours'] = 'Fenêtre de vérification (heures)';
$string['settings:unanswered_window_hours_desc'] = 'Profondeur d\'analyse de chaque exécution. Plus court réagit plus vite mais demande assez de trafic pour être significatif.';
$string['settings:unanswered_min_questions'] = 'Nombre minimal de questions avant alerte';
$string['settings:unanswered_min_questions_desc'] = 'Un cours n\'est évalué qu\'à partir de ce nombre de questions dans la fenêtre. En dessous, quelques apprenants fermant l\'onglet ressemblent à une panne.';
$string['settings:unanswered_min_answer_rate'] = 'Taux de réponse minimal';
$string['settings:unanswered_min_answer_rate_desc'] = 'Alerter lorsque la proportion de questions ayant reçu une réponse passe sous ce seuil. 0,5 détecte une panne partielle, pas seulement totale. Mettre 0 pour désactiver ce test.';

$string['settings:hidden_categories'] = 'Catégories de cours masquées';
$string['settings:hidden_categories_desc'] = 'Liste, séparée par des virgules, des noms ou identifiants de catégories de cours où l\'assistant ne doit pas apparaître. Exemple : "Développement de cours, 42". L\'assistant est également masqué automatiquement lorsque le mode édition est activé.';
$string['settings:provider_heading'] = 'Fournisseur d\'IA et conversation';
$string['settings:provider_heading_desc'] = 'Configurez le moteur d\'IA, le modèle et le comportement de la conversation.';
$string['settings:claude_temperature_allow_prefixes'] = 'Modèles Claude acceptant temperature';
$string['settings:claude_temperature_allow_prefixes_desc'] = 'Un préfixe de nom de modèle par ligne. Les modèles Anthropic dont le nom commence par l\'un d\'eux acceptent encore le paramètre d\'échantillonnage <code>temperature</code>. Pour tout modèle Claude ne correspondant à aucun préfixe, temperature est omis (les modèles de type raisonnement depuis Opus 4.7 le rejettent avec une erreur HTTP 400). Laissez vide pour utiliser la valeur par défaut fournie.';
$string['settings:max_tokens'] = 'Longueur maximale de réponse (jetons)';
$string['settings:max_tokens_desc'] = 'Nombre maximal de jetons par réponse de l\'IA. Des valeurs plus basses produisent des réponses plus courtes et plus rapides. 512 = ~2-3 phrases, 1024 = ~1-2 paragraphes, 2048 = explications plus longues. Mettez 0 pour ne pas fixer de limite (valeur par défaut du fournisseur).';
$string['settings:profile_update_interval'] = 'Intervalle de mise à jour du profil étudiant';
$string['settings:profile_update_interval_desc'] = 'Après ce nombre de messages de l\'étudiant dans un cours, l\'assistant génère (ou actualise) un profil d\'apprentissage résumant ses points forts, ses points faibles, son style d\'apprentissage et ses centres d\'intérêt. Le profil est injecté dans le prompt système afin de personnaliser les réponses. Mettez 0 pour désactiver. Par défaut : 10.';
$string['settings:enable_thinking'] = 'Raisonnement étendu (Claude uniquement)';
$string['settings:enable_thinking_desc'] = 'Active le raisonnement adaptatif pour les modèles Claude. Claude décide quand et dans quelle mesure raisonner sur un problème avant de répondre. Améliore la précision sur les questions complexes, mais augmente la consommation de jetons et la latence. Le contenu du raisonnement n\'est pas montré aux étudiants. Les autres fournisseurs ignorent ce réglage.';
$string['settings:rag_sources_heading'] = 'Sources de contenu RAG';
$string['settings:rag_sources_heading_desc'] = 'Choisissez les types de contenu de cours dont l\'indexeur RAG extrait le texte. Les indicateurs d\'état sur la <a href="{$a}">page d\'administration RAG</a> montrent si chaque extracteur dispose de ce dont il a besoin (par exemple le binaire pdftotext ou la liste d\'autorisation Cloudflare) pour fonctionner.';
$string['settings:rag_extract_pdf'] = 'Indexer les fichiers PDF (mod_resource)';
$string['settings:rag_extract_pdf_desc'] = 'Extrait le texte des PDF déposés via le binaire <code>pdftotext</code> (poppler). Détecte automatiquement le chemin du binaire ; indiquez-le ci-dessous si nécessaire.';
$string['settings:rag_pdftotext_path'] = 'Chemin du binaire pdftotext';
$string['settings:rag_pdftotext_path_desc'] = 'Laissez vide pour la détection automatique (vérifie <code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> et <code>which pdftotext</code>). Ne renseignez ce champ que si votre installation se trouve ailleurs.';
$string['settings:rag_extract_docx'] = 'Indexer les fichiers DOCX (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'Extrait le texte des documents Word déposés via ZipArchive de PHP. Aucune dépendance externe requise.';
$string['settings:rag_extract_pptx'] = 'Indexer les fichiers PPTX (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'Extrait le texte des présentations PowerPoint modernes déposées via ZipArchive de PHP. Parcourt le XML des diapositives et des notes du présentateur dans l\'ordre de la présentation ; aucune dépendance externe requise. Les anciens fichiers binaires <code>.ppt</code> ne sont pas pris en charge : réenregistrez ces présentations au format <code>.pptx</code>.';
$string['settings:rag_extract_h5p'] = 'Indexer le contenu H5P (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'Parcourt le JSON du contenu H5P et indexe tous les champs contenant du texte (questions, réponses, feedback, descriptions). Les métadonnées des types de contenu H5P sont larges ; attendez-vous à quelques faux positifs dans certains cas limites.';
$string['settings:rag_extract_scorm'] = 'Indexer les paquets SCORM (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'Décompresse les paquets SCORM et indexe <code>imsmanifest.xml</code>, les fichiers <code>.html</code> et les chaînes de contenu Articulate Storyline. <strong>Désactivé par défaut</strong>, car l\'analyse SCORM peut être coûteuse. La taille maximale du paquet est contrôlée par <code>rag_scorm_max_mb</code>.';
$string['settings:rag_scorm_max_mb'] = 'Taille maximale de paquet SCORM à indexer (Mo)';
$string['settings:rag_scorm_max_mb_desc'] = 'Ignore les paquets SCORM plus volumineux que cette valeur afin d\'éviter une consommation excessive de mémoire.';
$string['settings:rag_fetch_transcripts'] = 'Récupérer les transcriptions des vidéos et contenus interactifs intégrés';
$string['settings:rag_fetch_transcripts_desc'] = 'Analyse le contenu de mod_page et mod_book à la recherche d\'iframes intégrées (Synthesia, YouTube, Articulate, Genially) et récupère l\'URL de transcription associée à chaque intégration (en cherchant au-dessus comme au-dessous de l\'iframe). Nécessite un accès HTTPS sortant depuis ce serveur vers l\'hôte des transcriptions. <strong>Désactivé par défaut</strong> ; activez-le une fois que l\'hôte des transcriptions a autorisé ce serveur (par exemple via une règle d\'accès par IP Cloudflare).';
$string['settings:rag_iframe_host_patterns'] = 'Motifs d\'hôtes d\'iframe';
$string['settings:rag_iframe_host_patterns_desc'] = 'Une expression régulière par ligne correspondant à l\'attribut <code>src</code> d\'une iframe. Chaque iframe correspondante est traitée comme une intégration interactive dont la transcription doit être associée et indexée. Les lignes commençant par <code>#</code> sont des commentaires.';
$string['settings:rag_transcript_url_pattern'] = 'Motif d\'URL de transcription';
$string['settings:rag_transcript_url_pattern_desc'] = 'Expression régulière correspondant aux URL des liens de transcription. L\'indexeur choisit le lien correspondant le plus proche (au-dessus ou au-dessous) de chaque iframe détectée et les associe. Laissez vide pour désactiver l\'association des transcriptions.';
$string['settings:performance_heading'] = 'Performances';
$string['settings:performance_heading_desc'] = 'Contrôle la quantité de contenu de cours incluse dans le prompt de l\'IA. Des valeurs plus basses accélèrent les réponses mais donnent moins de contexte à l\'IA.';
$string['settings:max_content_per_resource'] = 'Contenu maximal par ressource (caractères)';
$string['settings:max_content_per_resource_desc'] = 'Nombre maximal de caractères de contenu extraits de chaque page ou chapitre de livre. Des valeurs plus basses réduisent la taille du prompt et accélèrent les réponses.';
$string['settings:max_total_content'] = 'Contenu total maximal (caractères)';
$string['settings:max_total_content_desc'] = 'Nombre total maximal de caractères de contenu de cours inclus dans le prompt système. Des valeurs plus basses réduisent la taille du prompt et accélèrent les réponses.';
$string['settings:spend_guard_heading'] = 'Garde-fou de dépenses et optimiseur';
$string['settings:spend_guard_heading_desc'] = 'Définissez des plafonds de dépenses LLM par période. [[tutorshort]] met les requêtes en pause lorsqu\'un plafond est atteint ou bascule vers un fournisseur moins coûteux de votre chaîne de secours. Consultez la <a href="{$a}">page Coût des jetons</a> pour l\'état actuel des dépenses et les recommandations de l\'optimiseur.';
$string['settings:spend_cap_period'] = 'Période du plafond de dépenses';
$string['settings:spend_cap_period_desc'] = 'Fréquence de réinitialisation du plafond de dépenses. Aligné sur le calendrier : mensuel démarre le 1er du mois, hebdomadaire le lundi et quotidien à minuit.';
$string['settings:spend_cap_site'] = 'Plafond de dépenses pour tout le site (USD)';
$string['settings:spend_cap_site_desc'] = 'Plafond total en USD pour tous les cours et toutes les fonctionnalités de la période en cours. <code>0</code> = illimité. Les plafonds par fonctionnalité ci-dessous priment sur celui-ci lorsqu\'ils sont définis.';
$string['settings:spend_cap_chat'] = 'Plafond du chat (USD)';
$string['settings:spend_cap_chat_desc'] = 'Plafond réservé à la charge de travail chat + quiz des étudiants. <code>0</code> = utiliser le plafond global du site.';
$string['settings:spend_cap_voice'] = 'Plafond de la voix (USD)';
$string['settings:spend_cap_voice_desc'] = 'Plafond pour la voix (Realtime + TTS + STT). La voix est généralement le poste le plus coûteux : plafonnez-la en premier.';
$string['settings:spend_cap_rag'] = 'Plafond RAG (USD)';
$string['settings:spend_cap_rag_desc'] = 'Plafond pour les appels d\'embeddings effectués lors de l\'indexation des cours.';
$string['settings:spend_cap_analytics'] = 'Plafond des analyses (USD)';
$string['settings:spend_cap_analytics_desc'] = 'Plafond pour les requêtes d\'administration de Learning Radar.';
$string['settings:spend_failover_chain'] = 'Chaîne de secours';
$string['settings:spend_failover_chain_desc'] = 'Lorsqu\'un plafond est atteint, [[tutorshort]] essaie ces fournisseurs dans l\'ordre. Une entrée par ligne, au format <code>capability:label</code>. Les libellés renvoient aux entrées des fournisseurs de comparaison (pour <code>chat</code> / <code>analytics</code>) ou des fournisseurs de voix (pour <code>voice</code>). Les lignes commençant par <code>#</code> sont des commentaires. Exemple :<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'Bascule de secours par appel (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'Lorsque cette option est activée, chaque appel de chat encapsule le fournisseur principal dans un décorateur de chaîne de secours. En cas de dépassement du délai d\'attente ou d\'erreur 5xx sur un appel, [[tutorshort]] passe à l\'entrée suivante de la <strong>chaîne de secours</strong> ci-dessus et ouvre un circuit de 15 minutes sur le fournisseur défaillant. Émet une ligne d\'audit (<code>failover_fallthrough</code>) à chaque bascule ; consultez Administration -> [[tutorshort]] -> Journal d\'audit après activation pour vérifier que la chaîne fonctionne correctement. Désactivé par défaut ; activez-le une fois la chaîne validée et une fois que votre établissement a confirmé que les clauses de traitement des données requises sont en place pour chacun de ses fournisseurs.';
$string['settings:failover_timeout_chat'] = 'Bascule par appel : délai d\'attente du chat (secondes)';
$string['settings:failover_timeout_chat_desc'] = 'Durée d\'attente du premier jeton d\'un fournisseur de chat avant de basculer. Par défaut 8 s. Des valeurs plus basses accélèrent la bascule sur les fournisseurs lents, au prix de faux positifs sur des requêtes ponctuellement lentes ; des valeurs plus élevées maintiennent la chaîne plus longtemps sur le fournisseur principal. Pris en compte uniquement lorsque la <strong>bascule de secours par appel</strong> est activée.';
$string['settings:spend_notify_emails'] = 'Destinataires des alertes de dépenses';
$string['settings:spend_notify_emails_desc'] = 'Adresses e-mail séparées par des virgules à prévenir à 80 %, 95 % et 100 % du plafond. Laissez vide pour prévenir tous les administrateurs du site.';
$string['settings:opt_cost_weight'] = 'Optimiseur : poids du coût';
$string['settings:opt_cost_weight_desc'] = 'Importance accordée par l\'optimiseur au coût lors du classement des fournisseurs. 0.0 ignore le coût, 1.0 optimise uniquement le coût. Doit être combiné avec le poids de la qualité.';
$string['settings:opt_quality_weight'] = 'Optimiseur : poids de la qualité';
$string['settings:opt_quality_weight_desc'] = 'Importance accordée par l\'optimiseur à la satisfaction des étudiants (taux de votes positifs) lors du classement des fournisseurs. 0.0 ignore la qualité.';
$string['settings:inactivity_reminder_enabled'] = 'Rappels d\'inactivité';
$string['settings:inactivity_reminder_enabled_desc'] = 'Envoie un e-mail hebdomadaire aux étudiants qui n\'ont pas accédé à leur cours depuis le nombre de jours configuré.';
$string['settings:inactivity_threshold_days'] = 'Seuil d\'inactivité (jours)';
$string['settings:inactivity_threshold_days_desc'] = 'Nombre de jours d\'inactivité avant l\'envoi d\'un e-mail de rappel.';
$string['settings:voice_providers_heading'] = 'Fournisseurs de voix (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Configurez un ou plusieurs fournisseurs d\'API vocale. Ces réglages sont indépendants du fournisseur de chat ci-dessus et du fournisseur d\'embeddings RAG : la voix dispose de sa propre liste de fournisseurs car seuls OpenAI et xAI exposent actuellement des points de terminaison Realtime par WebSocket, TTS et STT. Utilisez les listes déroulantes ci-dessous pour choisir quel fournisseur enregistré prend en charge chaque fonctionnalité. Si aucune ligne n\'est définie, le mécanisme hérité à clé unique est utilisé (clé API Realtime ci-dessus ou clé OpenAI principale). Un site utilisant Together AI / Anthropic / DeepSeek / Gemini / Mistral pour le chat doit configurer au moins une ligne ici pour que la voix fonctionne.';
$string['settings:voice_active_realtime'] = 'Fournisseur Realtime actif';
$string['settings:voice_active_realtime_desc'] = 'Quel fournisseur de voix configuré prend en charge les sessions de l\'agent vocal Realtime.';
$string['settings:voice_active_tts'] = 'Fournisseur TTS actif';
$string['settings:voice_active_tts_desc'] = 'Quel fournisseur de voix configuré prend en charge la lecture par synthèse vocale des réponses de l\'IA.';
$string['settings:voice_active_stt'] = 'Fournisseur STT actif';
$string['settings:voice_active_stt_desc'] = 'Quel fournisseur prend en charge la transcription en texte de l\'audio des étudiants. Laissez vide pour privilégier le serveur Whisper auto-hébergé lorsqu\'il est configuré ci-dessous, avec repli sur la première ligne de fournisseur de voix ou sur la clé héritée.';
$string['settings:stt_selfhosted_enabled'] = 'Activer la transcription auto-hébergée';
$string['settings:stt_selfhosted_enabled_desc'] = 'Utilise le serveur Whisper auto-hébergé ci-dessous comme voie de transcription pour la saisie vocale et Soapbox. Nécessite une URL de serveur ci-dessous. Lorsque cette option est désactivée, la transcription se replie sur la voie hébergée (OpenAI Whisper) ou sur celle du navigateur, même si une URL est renseignée.';
$string['settings:stt_selfhosted_warm'] = 'Préchauffer au démarrage d\'un enregistrement Soapbox';
$string['settings:stt_selfhosted_warm_desc'] = 'Lorsque cette option est activée, le démarrage d\'un enregistrement Soapbox envoie un ping de préchauffage léger, au mieux, au serveur de transcription auto-hébergé, afin qu\'un hôte avec mise à l\'échelle à zéro (par exemple Cloud Run) démarre pendant que l\'étudiant enregistre encore, masquant ainsi le délai de démarrage à froid pour la transcription lancée à l\'envoi. Sans effet si aucune URL de serveur auto-hébergé n\'est renseignée ci-dessus. Désactivé par défaut.';
$string['settings:voice_tab_enabled'] = 'Activer l\'onglet Voix';
$string['settings:voice_tab_enabled_desc'] = 'Affiche l\'onglet Voix dans la barre de navigation inférieure. Lorsqu\'il est désactivé, les étudiants ne voient que les onglets Chat et Notes. Les fonctionnalités vocales (pratique de conversation, pratique de prononciation) restent accessibles via les amorces de conversation si elles sont activées séparément.';
$string['settings:soapbox_heading'] = 'Soapbox';
$string['settings:soapbox_heading_desc'] = 'Entraînement à la présentation orale : comment les enregistrements sont transcrits et la grille d\'évaluation utilisée pour les noter. Activez Soapbox cours par cours à l\'aide du réglage pédagogique Soapbox dans la section Pédagogie.';
$string['settings:soapbox_max_seconds'] = 'Durée maximale d\'enregistrement Soapbox (secondes)';
$string['settings:soapbox_max_seconds_desc'] = 'Plafond absolu de la durée d\'enregistrement de tout devoir. Les enseignants peuvent définir une plage plus courte. Par défaut 720 (12 minutes).';
$string['settings:soapbox_max_recordings'] = 'Nombre maximal d\'enregistrements Soapbox par étudiant et par devoir';
$string['settings:soapbox_max_recordings_desc'] = 'Plafond absolu du nombre d\'enregistrements qu\'un étudiant peut réaliser pour un devoir, indépendamment du réglage des tentatives par devoir. Par défaut 3.';
$string['settings:soapbox_retention_days'] = 'Conservation des enregistrements Soapbox (jours)';
$string['settings:soapbox_retention_days_desc'] = 'Durée de conservation d\'un enregistrement avant suppression automatique ; la transcription, la note et le feedback sont conservés. Limité à une valeur comprise entre 1 et 28 jours. Plus la durée est courte, meilleure est la minimisation des données. Par défaut 7.';
$string['settings:soapbox_video_quality'] = 'Qualité vidéo Soapbox';
$string['settings:soapbox_video_quality_desc'] = 'Résolution et débit de l\'enregistrement. C\'est le principal levier de coût et de bande passante ; un présentateur filmé en plan rapproché reste lisible en qualité standard. La qualité basse convient aux connexions faibles ; la qualité haute uniquement lorsque le détail visuel compte.';
$string['settings:soapbox_storage_bucket'] = 'Bucket de stockage Soapbox';
$string['settings:soapbox_storage_bucket_desc'] = 'Bucket S3 pour les enregistrements. Par défaut : le bucket d\'archives partagé.';
$string['settings:soapbox_storage_region'] = 'Région de stockage Soapbox';
$string['settings:soapbox_storage_region_desc'] = 'Région AWS du bucket, par exemple us-east-1.';
$string['settings:soapbox_storage_prefix'] = 'Préfixe de clé de stockage Soapbox';
$string['settings:soapbox_storage_prefix_desc'] = 'Préfixe de clé au sein du bucket. Les enregistrements sont stockés sous ce chemin afin qu\'une règle de cycle de vie puisse les cibler.';
$string['settings:soapbox_storage_key'] = 'Identifiant de clé d\'accès du stockage Soapbox';
$string['settings:soapbox_storage_key_desc'] = 'Identifiant de clé d\'accès d\'un principal IAM limité à PutObject/GetObject/DeleteObject sur le préfixe ci-dessus.';
$string['settings:soapbox_storage_secret'] = 'Clé d\'accès secrète du stockage Soapbox';
$string['settings:soapbox_storage_secret_desc'] = 'Clé d\'accès secrète correspondant à l\'identifiant de clé d\'accès ci-dessus.';
