$string['quizlock:blocked'] = 'L\'assistant [[tutorshort]] n\'est pas disponible tant qu\'un test est en cours. Soumettez ou fermez votre tentative et il redeviendra disponible.';
$string['quizlock:heading'] = 'Mode test';
$string['quizlock:enabled'] = 'Verrouiller l\'assistant pendant les tests Moodle';
$string['quizlock:enabled_desc'] = 'Bloque l\'assistant partout (discussion, voix, cartes mémoire, tests d\'entraînement) tant qu\'un apprenant a une tentative de test en cours. La vérification se fait côté serveur : ouvrir un second onglet ne permet pas de contourner. Un enseignant peut exempter un test en réglant son niveau d\'assistance sur Aide complète.';
$string['quizlock:window'] = 'Fenêtre de validité de la tentative (minutes)';
$string['quizlock:window_desc'] = 'Durée pendant laquelle une tentative sur un test sans limite de temps compte encore comme en cours. Les tests ayant leur propre limite utilisent celle-ci. Les tentatives abandonnées restent en cours indéfiniment ; sans cette limite, l\'une d\'elles bloquerait l\'apprenant définitivement. Valeur par défaut : 180.';

$string['emergency:chat_stopped'] = '[[tutorshort]] est en pause pour le moment. Vos supports de cours ne sont pas affectés et cela ne vient pas de vous — merci de réessayer plus tard.';
$string['settings:money_nonnegative_invalid'] = 'Saisissez un montant supérieur ou égal à 0, avec deux décimales au maximum (par exemple 25 ou 25.50).';

$string['chat:turn_failed'] = 'Cette réponse n’a pas pu être terminée. Rien de ce que vous avez fait n’en est la cause — veuillez réessayer.';
$string['settings:prompt_budget_mode'] = 'Mode de budget du prompt système';
$string['settings:prompt_budget_mode_desc'] = 'Comment le budget de caractères du prompt système est déterminé. <strong>Déduire du modèle</strong> calcule la place réellement offerte par le modèle configuré — sa fenêtre de contexte, moins la réponse réservée et l’historique de la conversation — et retient cette valeur, plafonnée pour qu’une très grande fenêtre n’autorise pas un très grand prompt. Cela ne s’applique que tant que le budget de caractères ci-dessous reste à sa valeur par défaut de 36 000 : si vous modifiez ce nombre, c’est lui qui l’emporte, dans les deux sens, car un chiffre saisi par une personne administratrice est une décision et non une supposition. <strong>Fixe</strong> utilise toujours le nombre ci-dessous. Un backend auto-hébergé devrait renseigner la fenêtre de contexte du backend, qui prime sur tout ce qui précède.';
$string['settings:prompt_budget_mode_auto'] = 'Déduire du modèle (recommandé)';
$string['settings:prompt_budget_mode_fixed'] = 'Budget de caractères fixe';

$string['quizlock:scope'] = 'Jusqu’où va le verrouillage';
$string['quizlock:scope_course'] = 'Ce cours uniquement (recommandé)';
$string['quizlock:scope_site'] = 'Tous les cours';
$string['quizlock:scope_desc'] = 'Si une tentative en cours bloque [[tutorshort]] uniquement dans le cours contenant le test, ou partout. <strong>Ce cours uniquement</strong> est la valeur par défaut et convient presque toujours. À l’échelle du site était le comportement jusqu’à la v7.2.4, avec un défaut qu’il vaut mieux connaître : une tentative abandonnée reste « en cours » indéfiniment, si bien qu’un seul test oublié quelque part dans l’historique d’une personne désactivait l’assistant dans tous ses cours, sans la moindre explication à l’écran. À l’échelle du site n’apporte presque rien face à quelqu’un de déterminé, qui dispose d’un second navigateur, et le contenu comme la recherche de l’assistant sont de toute façon limités au cours.';

$string['settings:prompt_budget_tuner_conflict'] = 'La tâche obsolète d’ajustement automatique du budget de prompt est activée alors que le mode de budget est réglé pour être déduit du modèle. Les deux entrent en conflit : la tâche écrit le budget de caractères, et toute valeur autre que celle par défaut est lue comme un choix délibéré, ce qui désactive le budget déduit. La tâche se retire désormais d’elle-même dans ce mode, donc rien n’est écrasé — désactivez-la tout de même pour lever l’ambiguïté.';

$string['settings:prompt_budget_no_window'] = 'Le mode de budget ci-dessus est réglé pour être déduit du modèle, mais il n’y a rien à en déduire : le modèle de conversation n’est pas renseigné et aucune fenêtre de contexte du backend n’est configurée, si bien que la déduction retombe sur le budget de caractères fixe ci-dessous. Renseignez le modèle de conversation, ou saisissez la fenêtre de contexte du backend à la main, puis relancez l’autotest du backend et vérifiez que le contrôle de la fenêtre de contexte réussit. D’ici là, le budget est le nombre ci-dessous, quoi qu’affirme le mode.';

