$string['privacynotice:shared_item2'] = 'Un résumé du contenu du cours que vous étudiez';
$string['privacynotice:shared_item3'] = 'Les 10 derniers messages de votre conversation en cours avec [[tutorshort]]';
$string['privacynotice:shared_item4'] = 'Votre plan d\'étude, si vous en avez créé un';
$string['privacynotice:shared_item5'] = 'Votre résumé de profil, si vous en avez créé un';
$string['privacynotice:whosees_never'] = 'Voici ce que [[tutorshort]] ne partage jamais :';
