$string['privacynotice:notshared_item2'] = 'Votre adresse e-mail';
$string['privacynotice:notshared_item3'] = 'Votre nom d\'utilisateur Moodle ou votre numéro d\'identification';
$string['privacynotice:notshared_item4'] = 'Votre adresse postale';
$string['privacynotice:notshared_item5'] = 'Toute autre information susceptible de vous identifier personnellement';
$string['privacynotice:whosees_contract'] = '[[uniname]] n\'utilise que des services d\'IA que nous avons soigneusement examinés et approuvés. Chacun a un contrat avec [[uniname]] qui limite l\'usage qu\'il peut faire de vos informations et lui interdit d\'utiliser vos conversations avec [[tutorshort]] pour entraîner son IA.';
$string['privacynotice:retention'] = 'Combien de temps [[tutorshort]] conserve vos informations';
$string['privacynotice:retention_item1'] = 'Vos conversations sont conservées jusqu\'à ce que vous les supprimiez ou jusqu\'à ce que la période de conservation des conversations du site (deux ans d\'inactivité par défaut) les supprime automatiquement. Seuls les 10 derniers tours sont envoyés au modèle d\'IA.';
$string['privacynotice:retention_item2'] = 'Les notes, les plans d\'étude et les rappels sont conservés jusqu\'à ce que vous les supprimiez.';
$string['privacynotice:retention_item3'] = 'Les analyses anonymisées sont conservées conformément à la politique de conservation des documents de [[uniname]] et ne peuvent pas être reliées à vous.';
$string['privacynotice:retention_item4'] = 'Les journaux d\'audit et d\'exploitation sont conservés jusqu\'à 365 jours. Ils enregistrent qu\'un message a été envoyé — l\'heure, le cours et l\'adresse réseau d\'origine — mais jamais le contenu de ce que vous avez écrit. Ces entrées enregistrent votre identifiant utilisateur, pas votre nom ; lorsque la vue de ce journal côté administrateur affiche un nom, celui-ci est lu depuis l\'enregistrement de votre compte [[uniname]] existant.';
$string['privacynotice:retention_deletion'] = 'Lorsque votre compte utilisateur [[uniname]] est supprimé, toutes les données [[tutorshort]] liées à votre identifiant utilisateur sont supprimées dans la même opération.';
