$string['privacynotice:rights_download'] = 'Téléchargement.';
$string['privacynotice:rights_download_desc'] = 'La page des paramètres utilisateur propose un bouton « Télécharger mes données [[tutorshort]] » qui produit un fichier structuré contenant toutes vos données [[tutorshort]].';
$string['privacynotice:rights_delete'] = 'Suppression.';
$string['privacynotice:rights_delete_desc'] = 'La même page propose des options de suppression au niveau du cours et au niveau global. La suppression est immédiate.';
$string['privacynotice:rights_correction'] = 'Rectification.';
$string['privacynotice:rights_correction_desc'] = 'Les conversations avec [[tutorshort]] sont des transcriptions brutes et ne sont normalement pas modifiées. Si un enregistrement dérivé vous semble erroné, continuez à utiliser [[tutorshort]] ou contactez [[uniname]] à l\'adresse indiquée ci-dessous.';
$string['privacynotice:rights_object'] = 'Opposition ou limitation.';
$string['privacynotice:rights_object_desc'] = 'Vous n\'êtes pas obligé d\'utiliser [[tutorshort]]. Vous pouvez supprimer vos données à tout moment.';
$string['privacynotice:rights_portability'] = 'Portabilité.';
