$string['privacynotice:rights_complaint'] = 'Réclamation.';
$string['privacynotice:rights_complaint_desc'] = 'Contactez [[uniname]]. Les apprenants situés dans l\'UE, au Royaume-Uni, en Suisse, au Brésil ou au Canada peuvent également saisir leur autorité nationale de protection des données.';
$string['privacynotice:international'] = 'Apprenants internationaux';
$string['privacynotice:international_body'] = '[[uniname]] accueille des apprenants du monde entier. Si vous résidez dans une région dotée de règles spécifiques de protection des données (RGPD, RGPD britannique, LGPD, LPRPDE, LPD suisse, CCPA), ces règles s\'appliquent à vos données [[tutorshort]]. La base légale du traitement est l\'exécution du contrat de formation qui vous lie à [[uniname]], associée à l\'intérêt légitime de [[uniname]] à améliorer ses services de formation.';
$string['privacynotice:security'] = 'Sécurité';
$string['privacynotice:security_intro'] = '[[tutorshort]] vit à l\'intérieur de la plateforme Moodle de [[uniname]], vous devez donc être connecté pour l\'utiliser. Voici quelques mesures concrètes que nous prenons pour protéger vos informations :';
$string['privacynotice:security_transit'] = 'En transit :';
$string['privacynotice:security_transit_desc'] = 'Lorsque vos messages circulent entre votre appareil et [[tutorshort]], ils sont chiffrés. Autrement dit, si quelqu\'un tentait de les intercepter, il ne verrait que du code brouillé.';
$string['privacynotice:security_rest'] = 'Au repos :';
$string['privacynotice:security_rest_desc'] = 'Lorsque vos informations sont stockées, elles résident dans la base de données Moodle de [[uniname]], protégées par les mêmes contrôles de sécurité que [[uniname]] applique au reste de vos données d\'étudiant.';
$string['privacynotice:security_incident'] = 'Si quelque chose se passe mal :';
